ALTER POLICY auth_read_food_cancel_meals ON public.food_cancellation_request_meals TO authenticated USING (public.is_staff(auth.uid()));
ALTER POLICY auth_read_food_cancel ON public.food_cancellation_requests TO authenticated USING (public.is_staff(auth.uid()));
ALTER POLICY auth_read_transfer_requests ON public.transfer_requests TO authenticated USING (public.is_staff(auth.uid()));
DROP POLICY "System can insert checkout_reports" ON public.checkout_reports;
REVOKE INSERT ON public.checkout_reports FROM anon, authenticated;
COMMENT ON TABLE public.checkout_reports IS 'Checkout reports are generated by the protected generate_checkout_report trigger; client roles cannot insert reports directly.';